        pub fn descriptor_bytes(&self) -> &[u8] {
            &self.descriptor
        }

        /// ⚙️ Returns the optional executable identity.
        pub fn executable_identity(&self) -> Option<ArtifactExecutableIdentity> {
            self.executable_identity
        }

