        entry: std::mem::ManuallyDrop<Option<ChildContentEntry>>,
        metadata: std::mem::ManuallyDrop<Option<[String; 7]>>,
        metadata_cursor: usize,
        visibility: std::sync::Arc<semio_framework_os_kernel::os_vcs::ArtifactGroupVisibility>,
        generation: u64,
