    /// 🎒️ Immutable app state plus an owned reserved-route input. Implementations only construct a
    /// persistent job here; producer work belongs in that job's bounded `step` calls.
    pub struct ArtifactReservedToolJobRequest<A: ArtifactApp> {
        pub controller_id: String,
        pub tool_id: String,
        pub payload_schema_id: String,
        pub contract: semio_framework::ToolExecutionContract,
        pub app_instance_id: u32,
        /// 🌐️ Caller-selected ephemeral presentation axes, when a host context is present.
        pub ui_axes: Option<(semio_framework_ui_locale::Locale, semio_framework_ui_locale::Terminology)>,
        pub parent_document_id: String,
        pub canonical_base_revision: [u8; 32],
        pub authoring_seed: String,
        pub snapshot: std::sync::Arc<A::Snapshot>,
        pub config: std::sync::Arc<A::Config>,
        pub history: std::sync::Arc<HistoryView>,
        /// 🧩️ The parent's composed children, the same view `ArtifactView` hands the synchronous
        /// `A::import_media`. A composing app's LIVE scene is its children, not its own snapshot
        /// (sequence's steps live on the `content` Flow child), and the mounted route builds the emit
        /// exclusively from the resumable job — so without this a composed app could not write a
        /// resumable importer at all and every delivery died `interactive-job.missing-reserved-builder`
        /// (ticket 26/09/19/SEMIO-TECH-PLAY-GRID-WITH-EVERY-APP, media §8). Cheap to clone
        /// (`Option<Arc<ChildContentRoot>>`); a job releases it as soon as it has decoded.
        pub children: ChildContentView,
        pub raw_wire: Vec<u8>,
        pub input: ArtifactReservedToolInput,
        pub completion: ArtifactToolCompletion<A>,
    }

    pub trait ArtifactSnapshotDisposer<T>: Send {
        fn close_step(&mut self, snapshot: &mut Option<std::sync::Arc<T>>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault>;
        fn terminal_is_empty(&self, snapshot: &Option<std::sync::Arc<T>>) -> bool;
    }

    /// 🧹️ Optional exact-owner disposer retained until the associated artifact value is empty.
    pub type ArtifactDisposal<T> = Option<Box<dyn ArtifactOwnedDisposer<T>>>;

    /// 📬️ Mutation emission paired with its operation failure, without changing ownership.
    pub type ArtifactMutationOutcome<M, C = NoConfigMutation, D = NoDraftMutation, E = Fault> = Result<Emit<M, C, D>, E>;

    /// 🏗️ Admits initialization or returns the original document envelope.
    pub type ArtifactInitializationAdmission<S, M> = Result<ArtifactStoreInitializationJob<S, M>, ArtifactEnvelope<S, M>>;

    /// 📬️ Completed document mutations paired with their ephemeral output.
    type ArtifactToolEmission<A> = (ArtifactMutationOutcome<<A as ArtifactApp>::Mutation, <A as ArtifactApp>::ConfigMutation, <A as ArtifactApp>::DraftMutation>, EphemeralEmit<A>);

    /// 📖️ Non-capturing provider of one document schema, its semantic mutation roster and, row for row, each
    /// kind's leaf payload JSON Schema (`Mutation::INPUT_SCHEMAS`; shorter or empty when the aggregate publishes none).
    pub type OwnerMutationRoster = fn() -> (&'static str, &'static [protocol::SemanticDescriptor], &'static [&'static str]);

    pub trait ArtifactOwnedDisposer<T>: Send {
        fn close_step(&mut self, owner: &mut T, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault>;
        fn terminal_is_empty(&self, owner: &T) -> bool;
    }

    //#region 🎛️BoundedConfigStoreOwners
    struct BoundedConfigValueRetirement<T> {
        value: std::mem::ManuallyDrop<Option<T>>,
    }

    impl<T: Send + 'static> store::ErasedSnapshotRetirement for BoundedConfigValueRetirement<T> {
        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<store::SnapshotRetirementStep, semio_framework_value::ValueError> {
            if maximum_items == 0 || maximum_bytes < store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES {
                return Ok(store::SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(value) = self.value.take() {
                drop(value);
                return Ok(store::SnapshotRetirementStep::Pending { released_items: 1, released_bytes: store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES });
            }
            Ok(store::SnapshotRetirementStep::Complete)
        }

        fn terminal_is_empty(&self) -> bool {
            self.value.is_none()
        }
    }

    impl<T> Drop for BoundedConfigValueRetirement<T> {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.value.is_none(), "bounded config value retirement reached Drop before exact terminal emptiness");
        }
    }

