    /// ({@link store::ArtifactPackFiles}) via `store::print_document_pack`.
    pub async fn plugin_document_pack<PA: PluginApp>(runtime: &PluginRuntime<PA>, instance_id: u32) -> Result<store::ArtifactPackFiles, Fault> {
