        }
        frame_bytes.extend(typed_output.frames);
        Ok(PluginExchangeOutput {
            frames: frame_bytes,
            effects: effect_bytes,
            events: event_bytes,
            retry_command,
            command_terminal_fault,
            presence_pending,
            presence_terminal,
            presence_terminal_fault,
            typed_operation_results: typed_output.typed_operation_results,
        })
    }
