            vec![
                WindowMeasure::Toggle { id: format!("{id_prefix}-measure-sun-enabled"), icon_id: "sun".into(), label: Some(if is_de { "Aktiviert" } else { "Enabled" }.into()), pressed: sun.enabled, text: None, on_change: action("toggleSun", None) },
